import copy

import pytest
from hypothesis import given
import hypothesis.strategies as st


from intervals import merge_intervals


def reference_merge(intervals):
    """Obviously-correct reference: sort, merge iff next.start <= cur_end."""
    for s, e in intervals:
        if s > e:
            raise ValueError("invalid")
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    out = [tuple(ordered[0])]
    for s, e in ordered:
        ls, le = out[-1]
        if s <= le:
            if e > le:
                out[-1] = (ls, e)
        else:
            out.append((s, e))
    return out


def covered_points(intervals):
    pts = set()
    for s, e in intervals:
        pts.update(range(s, e + 1))
    return pts


small_interval = st.tuples(
    st.integers(min_value=-5, max_value=5),
    st.integers(min_value=0, max_value=5),
).map(lambda p: (p[0], p[0] + p[1]))

small_intervals = st.lists(small_interval, min_size=0, max_size=6)


# ---- explicit spec examples ----

def test_example_basic():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]


def test_example_touching():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]


def test_example_adjacent():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]


def test_example_unsorted():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]


def test_example_empty():
    assert merge_intervals([]) == []


def test_example_invalid():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# ---- defect-hunting: adjacent singleton must NOT merge ----

def test_adjacent_singleton_after_interval_stays_separate():
    assert merge_intervals([(1, 3), (4, 4)]) == [(1, 3), (4, 4)]


def test_adjacent_singletons_stay_separate():
    assert merge_intervals([(1, 1), (2, 2)]) == [(1, 1), (2, 2)]


def test_adjacent_singleton_before_interval_stays_separate():
    assert merge_intervals([(3, 3), (1, 2)]) == [(1, 2), (3, 3)]


def test_singleton_bridge_does_not_collapse_gap():
    # (3,3) is adjacent to both sides but shares no point with either
    assert merge_intervals([(1, 2), (4, 5), (3, 3)]) == [(1, 2), (3, 3), (4, 5)]


@given(st.integers(min_value=-20, max_value=20), st.integers(min_value=-20, max_value=20))
def test_property_singleton_adjacent_never_merges(a, b):
    # build a non-singleton interval ending at m, plus singleton at m+1
    lo = min(a, b)
    hi = max(a, b)
    # ensure first interval has length >= 1 so start != end
    if hi - lo < 1:
        hi = lo + 1
    singleton = hi + 1
    result = merge_intervals([(lo, hi), (singleton, singleton)])
    assert result == [(lo, hi), (singleton, singleton)]


@given(st.integers(min_value=-20, max_value=20))
def test_property_consecutive_singletons_never_merge(x):
    assert merge_intervals([(x, x), (x + 1, x + 1)]) == [(x, x), (x + 1, x + 1)]


# ---- general spec properties ----

@given(small_intervals)
def test_property_sorted_and_strictly_disjoint(intervals):
    result = merge_intervals([tuple(iv) for iv in intervals])
    for i in range(1, len(result)):
        assert result[i][0] > result[i - 1][1]
    starts = [s for s, _ in result]
    assert starts == sorted(starts)


@given(small_intervals)
def test_property_coverage_preserved(intervals):
    result = merge_intervals([tuple(iv) for iv in intervals])
    assert covered_points(result) == covered_points(intervals)


@given(small_intervals)
def test_property_equivalence_to_reference(intervals):
    result = merge_intervals([tuple(iv) for iv in intervals])
    assert result == reference_merge(intervals)


@given(small_intervals)
def test_property_idempotent(intervals):
    once = merge_intervals([tuple(iv) for iv in intervals])
    twice = merge_intervals(list(once))
    assert twice == once


@given(small_intervals)
def test_property_permutation_invariant(intervals):
    a = merge_intervals([tuple(iv) for iv in intervals])
    b = merge_intervals([tuple(iv) for iv in reversed(intervals)])
    assert a == b


@given(st.integers(min_value=-10, max_value=10), st.integers(min_value=0, max_value=10), st.integers(min_value=0, max_value=10))
def test_property_touching_merges(a, len1, len2):
    # (a, a+len1) and (a+len1, a+len1+len2) share point a+len1
    b = a + len1
    c = b + len2
    assert merge_intervals([(a, b), (b, c)]) == [(a, c)]


@given(st.integers(min_value=-10, max_value=10), st.integers(min_value=0, max_value=10), st.integers(min_value=0, max_value=10))
def test_property_adjacent_non_singleton_stays_separate(a, len1, extra):
    # intervals [a, b] and [b+1, b+1+extra] with second non-singleton unless extra==0;
    # only check extra >= 1 so implementation's singleton bug is excluded here
    b = a + len1
    c = b + 1 + extra
    # force second interval length >= 1
    if extra < 1:
        c = b + 2
    result = merge_intervals([(a, b), (b + 1, c)])
    assert result == [(a, b), (b + 1, c)]


@given(small_intervals)
def test_property_contained_absorbed(intervals):
    # adding an interval contained in the union must not change coverage
    result = merge_intervals([tuple(iv) for iv in intervals])
    if not result:
        return
    # pick first output interval and add a sub-interval of it
    s, e = result[0]
    mid_s = s
    mid_e = e
    if s < e:
        mid_s = s + 1
    new_input = list(intervals) + [(mid_s, mid_e)]
    assert merge_intervals([tuple(iv) for iv in new_input]) == result


def test_property_duplicates_collapse():
    assert merge_intervals([(1, 5), (1, 5), (1, 5)]) == [(1, 5)]
    assert merge_intervals([(2, 2), (2, 2)]) == [(2, 2)]


def test_property_transitive_chain():
    assert merge_intervals([(1, 2), (2, 3), (3, 4), (5, 6)]) == [(1, 4), (5, 6)]
    assert merge_intervals([(5, 6), (3, 4), (2, 3), (1, 2)]) == [(1, 4), (5, 6)]


def test_single_point_valid():
    assert merge_intervals([(2, 2)]) == [(2, 2)]
    assert merge_intervals([(2, 2), (5, 5)]) == [(2, 2), (5, 5)]


def test_invalid_among_valid_raises():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 3), (1, 1)])
    with pytest.raises(ValueError):
        merge_intervals([(0, 0), (10, 9)])


@given(small_intervals)
def test_property_input_never_mutated(intervals):
    original = [tuple(iv) for iv in intervals]
    snapshot = copy.deepcopy(original)
    merge_intervals(original)
    assert original == snapshot


def test_returns_new_list_of_tuples():
    inp = [(1, 3), (2, 4)]
    out = merge_intervals(inp)
    assert out == [(1, 4)]
    assert isinstance(out, list)
    assert all(type(x) is tuple for x in out)
    assert out is not inp
    # mutating output must not affect input
    out.append((100, 200))
    assert inp == [(1, 3), (2, 4)]


def test_empty_returns_new_empty_list():
    a = merge_intervals([])
    b = merge_intervals([])
    assert a == []
    assert a is not b


def test_negative_and_large_values():
    assert merge_intervals([(-10, -5), (-5, 0)]) == [(-10, 0)]
    assert merge_intervals([(-10, -5), (-4, 0)]) == [(-10, -5), (-4, 0)]
    big = 10 ** 9
    assert merge_intervals([(big, big), (big + 1, big + 1)]) == [(big, big), (big + 1, big + 1)]
    assert merge_intervals([(big, big + 5), (big + 5, big + 10)]) == [(big, big + 10)]
